svg.script:
(function () {
  var svg = document.currentScript.closest('svg');
  var q = function (c) { return svg.querySelector('.' + c); };
  var L = q('fig8-L'), LP = q('fig8-Lp'), ARR = q('fig8-arrow'), BUILD = q('fig8-build'),
      DOT = { P: q('fig8-P'), Q: q('fig8-Q'), R: q('fig8-R'), Rp: q('fig8-Rp') },
      FILL = q('fig8-fill'), KNOB = q('fig8-knob'), HIT = q('fig8-hit'),
      BTN = q('fig8-btn'), STEP = q('fig8-step'), PLAY = q('fig8-play'), PAUSE = q('fig8-pause');
  var lab = function (k) { return q('fig8-lab-' + k); };
  var P = [72.1, 167.89], Q = [135, 118], A = [16, 212.38], B = [263.6, 16];
  var LX = 219.29, LT = 22.72, LB = 288, RY = 51.15, RPY = 252.85;
  var TX0 = 95, TX1 = 243;

  var clamp = function (v) { return Math.min(1, Math.max(0, v)); };
  var ease = function (v) { v = clamp(v); return 0.5 - 0.5 * Math.cos(Math.PI * v); };
  var phase = function (s, a, b) { return ease((s - a) / (b - a)); };   // 0 before a, 1 after b
  var mix = function (u, v, k) { return [u[0] + (v[0] - u[0]) * k, u[1] + (v[1] - u[1]) * k]; };
  function line(el, u, v) {
    el.setAttribute('x1', u[0]); el.setAttribute('y1', u[1]);
    el.setAttribute('x2', v[0]); el.setAttribute('y2', v[1]);
  }
  function pop(el, k) { el.setAttribute('r', 5 * k); el.setAttribute('visibility', k > 0 ? 'visible' : 'hidden'); }
  function show(el, on) { el.style.opacity = on ? 1 : 0; }

  // The timeline, s from 0 to 1:
  //   0.00-0.06  P and Q appear
  //   0.10-0.24  step 1: L is drawn from P to Q, 0.24-0.36 then out to the edges
  //   0.38-0.44  step 2: R appears where L meets E again
  //   0.50-0.56  step 3: the arrow towards O appears, 0.58-0.86 L' is drawn
  //              down from it through R; R' appears as the line reaches it
  var STEPS = ['', 'Step 1: the line L through P and Q', 'Step 2: L meets E again at R',
               "Step 3: the line L' through O and R meets E again at R' = P + Q"];
  var s = 0;
  function draw() {
    var kx = TX0 + (TX1 - TX0) * s;
    KNOB.setAttribute('x', kx - 6); FILL.setAttribute('width', kx - TX0);
    KNOB.setAttribute('aria-valuenow', Math.round(s * 100));
    var step = s < 0.1 ? 0 : s < 0.38 ? 1 : s < 0.5 ? 2 : 3;
    KNOB.setAttribute('aria-valuetext', STEPS[step] || 'P and Q on E');
    STEP.textContent = step ? 'Step ' + step : '';

    var kp = phase(s, 0, 0.06);
    pop(DOT.P, kp); pop(DOT.Q, kp); show(lab('P'), kp > 0.5); show(lab('Q'), kp > 0.5);

    var k1 = phase(s, 0.10, 0.24), k2 = phase(s, 0.24, 0.36);
    L.setAttribute('visibility', k1 > 0 ? 'visible' : 'hidden');
    if (k2 > 0) line(L, mix(P, A, k2), mix(Q, B, k2)); else line(L, P, mix(P, Q, k1));
    show(lab('L'), k2 > 0.9);

    var kr = phase(s, 0.38, 0.44);
    pop(DOT.R, kr); show(lab('R'), kr > 0.5);

    var ko = phase(s, 0.50, 0.56);
    ARR.style.opacity = ko; show(lab('O'), ko > 0.5);
    var k3 = phase(s, 0.58, 0.86), y = LT + (LB - LT) * k3;
    LP.setAttribute('visibility', k3 > 0 ? 'visible' : 'hidden');
    line(LP, [LX, LT], [LX, y]);
    show(lab('Lp'), y > (RY + RPY) / 2);
    var krp = clamp((y - RPY) / 18);
    pop(DOT.Rp, krp); show(lab('Rp'), krp > 0.5);
  }

  // Playback: build up, pausing for a second as each step completes, hold
  // the finished picture, fade out, stay blank for a moment (long enough for
  // the labels' fade transitions to finish, so nothing flashes), start again.
  var reduce = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
  var RATE = 8640;                                     // ms per unit of s
  var PLAN = [[0, 0.36], 1000, [0.36, 0.44], 1000, [0.44, 1], 2500];
  var FADE = 700, BLANK = 600;
  var segs = [], T = 0;
  PLAN.forEach(function (g) {
    var d = typeof g === 'number' ? g : (g[1] - g[0]) * RATE;
    segs.push({ t0: T, d: d, g: g }); T += d;
  });
  var BUILT = T; T += FADE + BLANK;
  function at(t) {                                     // time in the cycle -> [s, opacity]
    if (t >= BUILT) {
      var u = t - BUILT;
      return u < FADE ? [1, 1 - u / FADE] : [0, 0];
    }
    for (var i = 0; i < segs.length; i++) {
      var g = segs[i];
      if (t < g.t0 + g.d) {
        if (typeof g.g === 'number') return [segs[i - 1].g[1], 1];
        return [g.g[0] + (g.g[1] - g.g[0]) * (t - g.t0) / g.d, 1];
      }
    }
    return [1, 1];
  }
  function timeOf(v) {                                 // first time in the cycle at which s = v
    if (v >= 1) return 0;                              // finished: start over
    for (var i = 0; i < segs.length; i++) {
      var g = segs[i].g;
      if (typeof g !== 'number' && v <= g[1]) return segs[i].t0 + (v - g[0]) * RATE;
    }
    return 0;
  }
  var playing = false, visible = true, start = null;
  function frame(ts) {
    if (!playing) return;
    if (visible) {
      if (start === null) start = ts - timeOf(s);
      var r = at((ts - start) % T);
      s = r[0]; BUILD.style.opacity = r[1];
      draw();
    } else {
      start = null;
    }
    requestAnimationFrame(frame);
  }
  function setPlaying(on) {
    playing = on;
    PLAY.setAttribute('visibility', on ? 'hidden' : 'visible');
    PAUSE.setAttribute('visibility', on ? 'visible' : 'hidden');
    BTN.setAttribute('aria-label', on ? 'Pause animation' : 'Play animation');
    if (on) { start = null; requestAnimationFrame(frame); }
    else BUILD.style.opacity = 1;
  }
  if ('IntersectionObserver' in window) {
    new IntersectionObserver(function (es) { visible = es[0].isIntersecting; }).observe(svg);
  }
  function stop() { if (playing) setPlaying(false); }
  BTN.style.cursor = 'pointer';
  BTN.addEventListener('click', function () { setPlaying(!playing); });
  BTN.addEventListener('keydown', function (ev) {
    if (ev.key === 'Enter' || ev.key === ' ') { setPlaying(!playing); ev.preventDefault(); }
  });

  function setFromEvent(ev) {
    var pt = svg.createSVGPoint(); pt.x = ev.clientX; pt.y = ev.clientY;
    var x = pt.matrixTransform(svg.getScreenCTM().inverse()).x;
    s = clamp((x - TX0) / (TX1 - TX0));
    draw();
  }
  var dragging = false;
  [KNOB, HIT].forEach(function (el) {
    el.style.cursor = 'pointer';
    el.addEventListener('pointerdown', function (ev) {
      stop(); dragging = true; el.setPointerCapture(ev.pointerId); setFromEvent(ev); ev.preventDefault();
    });
    el.addEventListener('pointermove', function (ev) { if (dragging) setFromEvent(ev); });
    el.addEventListener('pointerup', function () { dragging = false; });
  });
  KNOB.addEventListener('keydown', function (ev) {
    var d = { ArrowRight: 0.05, ArrowUp: 0.05, ArrowLeft: -0.05, ArrowDown: -0.05 }[ev.key];
    if (ev.key === 'Home') d = -1; if (ev.key === 'End') d = 1;
    if (d === undefined) return;
    stop(); s = clamp(s + d); draw(); ev.preventDefault();
  });
  s = reduce ? 1 : 0;
  draw();
  setPlaying(!reduce);
})();
